class AutoResource {
    int* resource_data;
public:
    AutoResource(size_t size)
        : resource_data(new int[size]) {} // Resource Acquisition
    ~AutoResource() {
        delete[] resource_data;           // Resource Release (Guaranteed)
    }

    // Essential ownership rule: Prevent copying raw resource pointers
    AutoResource(const AutoResource&) = delete;
    AutoResource& operator=(const AutoResource&) = delete;
};

